spec.query:
from (bucket: "my-bucket")
  |> range(start: v.timeRangeStart, stop: v.timeRangeStop)
  |> filter(fn: (r) => r["_measurement"] == "utilities")
  |> filter(fn: (r) => r["_field"] == "electricity_generation" or r["_field"] == "electricity_consumption")
  |> derivative(unit: 1h, columns: ["_value"], timeColumn: "_time")
  |> pivot(rowKey:["_time"], columnKey: ["_field"], valueColumn: "_value")
  |> map(fn: (r) => ({
      _time: r._time,
      electricity_ratio: r.electricity_generation / r.electricity_consumption
  }))

