  |> filter(fn: (r) => r["_field"] == "electricity_generation" or r["_field"] == "electricity_consumption")
  |> derivative(unit: 30d, columns: ["_value"], timeColumn: "_time")
  |> pivot(rowKey:["_time"], columnKey: ["_field"], valueColumn: "_value")
  |> map(fn: (r) => ({
      _time: r._time,
      net_profit: (r.electricity_generation * 0.1050) - (r.electricity_consumption * 0.1365)
  }))

